/**
 * arXiv Adapter - arXiv API search
 */

import { AbstractSearchAdapter, type AdapterMeta } from './base';
import type { SearchResult } from '../types';
import { parseArxivXml } from '../../../shared/utils';
import { getErrorMessage } from '../../../shared/errors';

const ARXIV_API_URL = 'http://export.arxiv.org/api/query';

export class ArxivAdapter extends AbstractSearchAdapter {
  readonly meta: AdapterMeta = {
    name: 'arXiv',
    sourceId: 'arxiv',
    tier: 'free',
    domains: ['physics', 'cs', 'general'],
    rateLimit: { requests: 3, windowMs: 1000 },
    description: 'Open access preprint repository for physics, mathematics, CS, and more'
  };

  isAvailable(): boolean {
    return true; // No API key required
  }

  async search(query: string, limit: number): Promise<SearchResult[]> {
    try {
      const searchQuery = encodeURIComponent(`all:${query}`);
      const url = `${ARXIV_API_URL}?search_query=${searchQuery}&max_results=${limit}&sortBy=relevance`;

      const response = await this.rateLimitedFetch(url, undefined, { maxRetries: 3 });
      const text = await response.text();

      const entries = parseArxivXml(text);
      return entries.map(entry => ({
        id: entry.id,
        title: entry.title,
        authors: entry.authors,
        abstract: entry.abstract,
        publishDate: entry.published,
        source: 'arxiv',
        url: `https://arxiv.org/abs/${entry.id}`,
        pdfUrl: entry.pdfUrl,
        keywords: entry.categories,
        openAccess: true
      }));
    } catch (error) {
      console.error('arXiv search error:', getErrorMessage(error));
      return [];
    }
  }
}

/**
 * Search Source Adapter - Base Interface & Abstract Class
 * 搜索源适配器基类
 */

import type { SearchResult } from '../types';
import type { SearchSource } from '../../../shared/types';
import { fetchWithRetry } from '../../../shared/utils';
import type { RetryOptions } from '../../../shared/types';

/** Source tier classification */
export type SourceTier = 'free' | 'freemium' | 'paid';

/** Academic domain coverage */
export type SourceDomain = 'general' | 'biomedical' | 'cs' | 'engineering' | 'physics' | 'multidisciplinary';

/** Adapter metadata */
export interface AdapterMeta {
  name: string;
  sourceId: SearchSource;
  tier: SourceTier;
  domains: SourceDomain[];
  rateLimit: { requests: number; windowMs: number };
  description: string;
}

/**
 * SearchSourceAdapter interface - contract for all search adapters
 */
export interface SearchSourceAdapter {
  readonly meta: AdapterMeta;

  /** Check if this adapter is available (API keys present, etc.) */
  isAvailable(): boolean;

  /** Execute a search query */
  search(query: string, limit: number): Promise<SearchResult[]>;

  /** Optional: resolve PDF URL for a given result */
  getPdfUrl?(result: SearchResult): Promise<string | undefined>;
}

/**
 * AbstractSearchAdapter - provides common functionality
 */
export abstract class AbstractSearchAdapter implements SearchSourceAdapter {
  abstract readonly meta: AdapterMeta;

  abstract isAvailable(): boolean;
  abstract search(query: string, limit: number): Promise<SearchResult[]>;

  private lastRequestTime = 0;

  /**
   * Rate-limited fetch wrapper
   */
  protected async rateLimitedFetch(
    url: string,
    init?: RequestInit,
    retryOpts?: RetryOptions
  ): Promise<Response> {
    const { requests, windowMs } = this.meta.rateLimit;
    const minInterval = windowMs / requests;

    const now = Date.now();
    const elapsed = now - this.lastRequestTime;
    if (elapsed < minInterval) {
      await new Promise(resolve => setTimeout(resolve, minInterval - elapsed));
    }

    this.lastRequestTime = Date.now();
    return fetchWithRetry(url, init, retryOpts ?? { maxRetries: 2 });
  }
}

/**
 * CORE Adapter - Open access full text
 * Requires API key for access
 */

import { AbstractSearchAdapter, type AdapterMeta } from './base';
import type { SearchResult } from '../types';
import { getErrorMessage } from '../../../shared/errors';

const CORE_API_URL = 'https://api.core.ac.uk/v3/search/works';

export class CoreAdapter extends AbstractSearchAdapter {
  readonly meta: AdapterMeta = {
    name: 'CORE',
    sourceId: 'core',
    tier: 'freemium',
    domains: ['general', 'multidisciplinary'],
    rateLimit: { requests: 1, windowMs: 10000 }, // 1 req/10s on free tier
    description: 'Open access aggregator with full text from 10K+ repositories'
  };

  private apiKey?: string;

  constructor(apiKey?: string) {
    super();
    this.apiKey = apiKey || process.env.CORE_API_KEY;
  }

  isAvailable(): boolean {
    return !!this.apiKey;
  }

  async search(query: string, limit: number): Promise<SearchResult[]> {
    if (!this.apiKey) return [];

    try {
      const url = `${CORE_API_URL}?q=${encodeURIComponent(query)}&limit=${limit}`;

      const response = await this.rateLimitedFetch(url, {
        headers: {
          'Authorization': `Bearer ${this.apiKey}`
        }
      });
      const data = await response.json() as {
        results?: Array<{
          id?: string;
          title?: string;
          authors?: Array<{ name?: string }>;
          abstract?: string;
          yearPublished?: number;
          doi?: string;
          downloadUrl?: string;
          sourceFulltextUrls?: string[];
          citationCount?: number;
          journals?: Array<{ title?: string }>;
        }>;
      };

      if (!data.results) return [];

      return data.results.map(work => ({
        id: `core:${work.id || ''}`,
        title: work.title || '',
        authors: work.authors?.map(a => a.name || '').filter(Boolean) || [],
        abstract: work.abstract || '',
        publishDate: work.yearPublished?.toString() || '',
        source: 'core',
        url: work.doi ? `https://doi.org/${work.doi}` : (work.sourceFulltextUrls?.[0] || ''),
        doi: work.doi,
        pdfUrl: work.downloadUrl,
        citations: work.citationCount,
        journal: work.journals?.[0]?.title,
        openAccess: true
      }));
    } catch (error) {
      console.error('CORE search error:', getErrorMessage(error));
      return [];
    }
  }

  async getPdfUrl(result: SearchResult): Promise<string | undefined> {
    if (!this.apiKey || !result.doi) return undefined;
    // CORE already provides download URLs in search results
    return result.pdfUrl;
  }
}

/**
 * CrossRef Adapter - DOI registration and metadata
 * 150M+ records, excellent for DOI resolution
 */

import { AbstractSearchAdapter, type AdapterMeta } from './base';
import type { SearchResult, CrossRefWork } from '../types';
import { getErrorMessage } from '../../../shared/errors';

const CROSSREF_API_URL = 'https://api.crossref.org/works';

export class CrossRefAdapter extends AbstractSearchAdapter {
  readonly meta: AdapterMeta = {
    name: 'CrossRef',
    sourceId: 'crossref',
    tier: 'free',
    domains: ['general', 'multidisciplinary'],
    rateLimit: { requests: 5, windowMs: 1000 },
    description: 'Official DOI registration agency with 150M+ metadata records'
  };

  private mailto?: string;

  constructor(mailto?: string) {
    super();
    this.mailto = mailto || process.env.CROSSREF_MAILTO;
  }

  isAvailable(): boolean {
    return true; // No API key required
  }

  async search(query: string, limit: number): Promise<SearchResult[]> {
    try {
      const url = `${CROSSREF_API_URL}?query=${encodeURIComponent(query)}&rows=${limit}&sort=relevance`;

      const headers: Record<string, string> = {};
      if (this.mailto) {
        headers['User-Agent'] = `ScholarGraph/1.0 (mailto:${this.mailto})`;
      }

      const response = await this.rateLimitedFetch(url, { headers });
      const data = await response.json() as {
        message?: { items?: CrossRefWork[] };
      };

      if (!data.message?.items) return [];

      return data.message.items.map((work) => {
        const authors = work.author?.map(a => {
          const parts = [a.given, a.family].filter(Boolean);
          return parts.join(' ');
        }) || [];

        const dateParts = work['published-print']?.['date-parts']?.[0]
          || work['published-online']?.['date-parts']?.[0];
        const publishDate = dateParts
          ? dateParts.filter(Boolean).join('-')
          : '';

        // Find PDF link if available
        const pdfLink = work.link?.find(l => l['content-type']?.includes('pdf'));

        return {
          id: `doi:${work.DOI}`,
          title: work.title?.[0] || '',
          authors,
          abstract: work.abstract?.replace(/<[^>]*>/g, '') || '', // Strip JATS XML tags
          publishDate,
          source: 'crossref',
          url: work.URL || `https://doi.org/${work.DOI}`,
          doi: work.DOI,
          citations: work['is-referenced-by-count'],
          venue: work['container-title']?.[0],
          journal: work['container-title']?.[0],
          pdfUrl: pdfLink?.URL
        };
      });
    } catch (error) {
      console.error('CrossRef search error:', getErrorMessage(error));
      return [];
    }
  }
}

/**
 * DBLP Adapter - Computer science bibliography
 */

import { AbstractSearchAdapter, type AdapterMeta } from './base';
import type { SearchResult, DblpHit } from '../types';
import { getErrorMessage } from '../../../shared/errors';

const DBLP_API_URL = 'https://dblp.org/search/publ/api';

export class DblpAdapter extends AbstractSearchAdapter {
  readonly meta: AdapterMeta = {
    name: 'DBLP',
    sourceId: 'dblp',
    tier: 'free',
    domains: ['cs'],
    rateLimit: { requests: 1, windowMs: 1000 },
    description: 'Computer science bibliography with comprehensive CS publication coverage'
  };

  isAvailable(): boolean {
    return true; // No API key required
  }

  async search(query: string, limit: number): Promise<SearchResult[]> {
    try {
      const url = `${DBLP_API_URL}?q=${encodeURIComponent(query)}&format=json&h=${limit}`;

      const response = await this.rateLimitedFetch(url);
      const data = await response.json() as {
        result?: { hits?: { hit?: DblpHit[] } };
      };

      const hits = data.result?.hits?.hit;
      if (!hits) return [];

      return hits.map((hit, index) => {
        const info = hit.info;

        // Parse authors - can be array or single object
        let authors: string[] = [];
        if (info.authors?.author) {
          const authorData = info.authors.author;
          if (Array.isArray(authorData)) {
            authors = authorData.map(a => a.text);
          } else {
            authors = [authorData.text];
          }
        }

        return {
          id: `dblp_${index}`,
          title: info.title || '',
          authors,
          abstract: '', // DBLP doesn't provide abstracts
          publishDate: info.year || '',
          source: 'dblp',
          url: info.ee || info.url || '',
          doi: info.doi,
          venue: info.venue
        };
      });
    } catch (error) {
      console.error('DBLP search error:', getErrorMessage(error));
      return [];
    }
  }
}

/**
 * Google Scholar Adapter (via SerpAPI)
 * Requires SERPAPI_KEY
 */

import { AbstractSearchAdapter, type AdapterMeta } from './base';
import type { SearchResult } from '../types';
import { getErrorMessage } from '../../../shared/errors';

const SERPAPI_URL = 'https://serpapi.com/search';

export class GoogleScholarAdapter extends AbstractSearchAdapter {
  readonly meta: AdapterMeta = {
    name: 'Google Scholar',
    sourceId: 'google_scholar',
    tier: 'paid',
    domains: ['general', 'multidisciplinary', 'cs', 'biomedical', 'engineering', 'physics'],
    rateLimit: { requests: 1, windowMs: 2000 },
    description: 'Google Scholar search via SerpAPI proxy'
  };

  private apiKey?: string;

  constructor(apiKey?: string) {
    super();
    this.apiKey = apiKey || process.env.SERPAPI_KEY;
  }

  isAvailable(): boolean {
    return !!this.apiKey;
  }

  async search(query: string, limit: number): Promise<SearchResult[]> {
    if (!this.apiKey) return [];

    try {
      const url = `${SERPAPI_URL}?engine=google_scholar&q=${encodeURIComponent(query)}&num=${limit}&api_key=${this.apiKey}`;

      const response = await this.rateLimitedFetch(url);
      const data = await response.json() as {
        organic_results?: Array<{
          position?: number;
          title?: string;
          result_id?: string;
          link?: string;
          snippet?: string;
          publication_info?: {
            summary?: string;
            authors?: Array<{ name: string }>;
          };
          inline_links?: {
            cited_by?: { total?: number };
          };
          resources?: Array<{
            title?: string;
            file_format?: string;
            link?: string;
          }>;
        }>;
      };

      if (!data.organic_results) return [];

      return data.organic_results.map((result, index) => {
        const pdfResource = result.resources?.find(r =>
          r.file_format?.toLowerCase() === 'pdf' || r.link?.endsWith('.pdf')
        );

        const authors = result.publication_info?.authors?.map(a => a.name) || [];
        // Try to extract year from publication summary
        const yearMatch = result.publication_info?.summary?.match(/\b(19|20)\d{2}\b/);

        return {
          id: result.result_id || `gs_${index}`,
          title: result.title || '',
          authors,
          abstract: result.snippet || '',
          publishDate: yearMatch ? yearMatch[0] : '',
          source: 'google_scholar',
          url: result.link || '',
          pdfUrl: pdfResource?.link,
          citations: result.inline_links?.cited_by?.total,
          snippet: result.snippet
        };
      });
    } catch (error) {
      console.error('Google Scholar search error:', getErrorMessage(error));
      return [];
    }
  }
}

/**
 * IEEE Xplore Adapter
 * Engineering/EE/CS papers, requires API key
 */

import { AbstractSearchAdapter, type AdapterMeta } from './base';
import type { SearchResult } from '../types';
import { getErrorMessage } from '../../../shared/errors';

const IEEE_API_URL = 'https://ieeexploreapi.ieee.org/api/v1/search/articles';

export class IeeeAdapter extends AbstractSearchAdapter {
  readonly meta: AdapterMeta = {
    name: 'IEEE Xplore',
    sourceId: 'ieee',
    tier: 'freemium',
    domains: ['engineering', 'cs'],
    rateLimit: { requests: 3, windowMs: 1000 },
    description: 'IEEE digital library for engineering, CS, and EE research'
  };

  private apiKey?: string;

  constructor(apiKey?: string) {
    super();
    this.apiKey = apiKey || process.env.IEEE_API_KEY;
  }

  isAvailable(): boolean {
    return !!this.apiKey;
  }

  async search(query: string, limit: number): Promise<SearchResult[]> {
    if (!this.apiKey) return [];

    try {
      const url = `${IEEE_API_URL}?apikey=${this.apiKey}&querytext=${encodeURIComponent(query)}&max_records=${limit}&sort_field=article_title&sort_order=asc`;

      const response = await this.rateLimitedFetch(url);
      const data = await response.json() as {
        articles?: Array<{
          article_number?: string;
          title?: string;
          authors?: { authors: Array<{ full_name: string }> };
          abstract?: string;
          publication_year?: string;
          publication_title?: string;
          doi?: string;
          html_url?: string;
          pdf_url?: string;
          citing_paper_count?: number;
          is_open_access?: boolean;
        }>;
      };

      if (!data.articles) return [];

      return data.articles.map(article => ({
        id: `ieee:${article.article_number || ''}`,
        title: article.title || '',
        authors: article.authors?.authors.map(a => a.full_name) || [],
        abstract: article.abstract || '',
        publishDate: article.publication_year || '',
        source: 'ieee',
        url: article.html_url || `https://ieeexplore.ieee.org/document/${article.article_number}`,
        doi: article.doi,
        pdfUrl: article.pdf_url,
        citations: article.citing_paper_count,
        venue: article.publication_title,
        journal: article.publication_title,
        openAccess: article.is_open_access
      }));
    } catch (error) {
      console.error('IEEE Xplore search error:', getErrorMessage(error));
      return [];
    }
  }
}

