/**
 * OpenAlex Adapter - Open scholarly metadata
 * 250M+ records, comprehensive coverage
 */

import { AbstractSearchAdapter, type AdapterMeta } from './base';
import type { SearchResult, OpenAlexWork } from '../types';
import { reconstructAbstract } from '../../../shared/utils';
import { getErrorMessage } from '../../../shared/errors';

const OPENALEX_API_URL = 'https://api.openalex.org/works';

export class OpenAlexAdapter extends AbstractSearchAdapter {
  readonly meta: AdapterMeta = {
    name: 'OpenAlex',
    sourceId: 'openalex',
    tier: 'free',
    domains: ['general', 'multidisciplinary', 'biomedical', 'cs', 'physics', 'engineering'],
    rateLimit: { requests: 10, windowMs: 1000 },
    description: 'Open catalog of 250M+ scholarly works, authors, venues, and concepts'
  };

  private mailto?: string;

  constructor(mailto?: string) {
    super();
    this.mailto = mailto || process.env.OPENALEX_MAILTO;
  }

  isAvailable(): boolean {
    return true; // No API key required
  }

  async search(query: string, limit: number): Promise<SearchResult[]> {
    try {
      let url = `${OPENALEX_API_URL}?search=${encodeURIComponent(query)}&per_page=${limit}`;
      if (this.mailto) {
        url += `&mailto=${encodeURIComponent(this.mailto)}`;
      }

      const response = await this.rateLimitedFetch(url);
      const data = await response.json() as { results?: OpenAlexWork[] };

      if (!data.results) return [];

      return data.results.map((work) => {
        const abstract = work.abstract_inverted_index
          ? reconstructAbstract(work.abstract_inverted_index)
          : '';

        const authors = work.authorships?.map(a => a.author.display_name) || [];
        const doi = work.doi?.replace('https://doi.org/', '');

        return {
          id: work.id.replace('https://openalex.org/', ''),
          title: work.display_name || work.title || '',
          authors,
          abstract,
          publishDate: work.publication_date || work.publication_year?.toString() || '',
          source: 'openalex',
          url: work.doi || work.id,
          doi,
          pdfUrl: work.best_oa_location?.pdf_url || work.open_access?.oa_url,
          citations: work.cited_by_count,
          venue: work.primary_location?.source?.display_name,
          openAccess: work.is_oa || work.open_access?.is_oa,
          concepts: work.concepts?.filter(c => c.score > 0.3).map(c => c.display_name)
        };
      });
    } catch (error) {
      console.error('OpenAlex search error:', getErrorMessage(error));
      return [];
    }
  }
}

/**
 * PubMed Adapter - NCBI E-utilities
 * Best for biomedical/life sciences
 */

import { AbstractSearchAdapter, type AdapterMeta } from './base';
import type { SearchResult } from '../types';
import { parsePubMedXml } from '../../../shared/utils';
import { getErrorMessage } from '../../../shared/errors';

const EUTILS_BASE = 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils';

export class PubMedAdapter extends AbstractSearchAdapter {
  readonly meta: AdapterMeta = {
    name: 'PubMed',
    sourceId: 'pubmed',
    tier: 'free',
    domains: ['biomedical'],
    rateLimit: { requests: 3, windowMs: 1000 },
    description: 'NCBI biomedical literature database with 35M+ citations'
  };

  private apiKey?: string;

  constructor(apiKey?: string) {
    super();
    this.apiKey = apiKey || process.env.NCBI_API_KEY;
    // With API key, rate limit is 10/s
    if (this.apiKey) {
      (this.meta as AdapterMeta).rateLimit = { requests: 10, windowMs: 1000 };
    }
  }

  isAvailable(): boolean {
    return true; // Works without API key (lower rate limit)
  }

  async search(query: string, limit: number): Promise<SearchResult[]> {
    try {
      // Step 1: esearch to get PMIDs
      let searchUrl = `${EUTILS_BASE}/esearch.fcgi?db=pubmed&term=${encodeURIComponent(query)}&retmax=${limit}&retmode=json`;
      if (this.apiKey) searchUrl += `&api_key=${this.apiKey}`;

      const searchResp = await this.rateLimitedFetch(searchUrl);
      const searchData = await searchResp.json() as {
        esearchresult?: { idlist?: string[] };
      };

      const pmids = searchData.esearchresult?.idlist;
      if (!pmids || pmids.length === 0) return [];

      // Step 2: efetch to get article details
      let fetchUrl = `${EUTILS_BASE}/efetch.fcgi?db=pubmed&id=${pmids.join(',')}&rettype=xml&retmode=xml`;
      if (this.apiKey) fetchUrl += `&api_key=${this.apiKey}`;

      const fetchResp = await this.rateLimitedFetch(fetchUrl);
      const xml = await fetchResp.text();

      const articles = parsePubMedXml(xml);

      return articles.map(article => ({
        id: `pmid:${article.pmid}`,
        title: article.title,
        authors: article.authors,
        abstract: article.abstract,
        publishDate: article.publishDate,
        source: 'pubmed',
        url: `https://pubmed.ncbi.nlm.nih.gov/${article.pmid}/`,
        doi: article.doi,
        journal: article.journal,
        meshTerms: article.meshTerms,
        pdfUrl: article.doi ? `https://doi.org/${article.doi}` : undefined
      }));
    } catch (error) {
      console.error('PubMed search error:', getErrorMessage(error));
      return [];
    }
  }
}

/**
 * Search Source Registry
 * 搜索源注册表 - 管理所有可用的搜索适配器
 */

import type { SearchSourceAdapter, SourceTier, SourceDomain } from './base';
import type { SearchSource } from '../../../shared/types';

export class SearchSourceRegistry {
  private adapters = new Map<SearchSource, SearchSourceAdapter>();

  /**
   * Register an adapter
   */
  register(adapter: SearchSourceAdapter): void {
    this.adapters.set(adapter.meta.sourceId, adapter);
  }

  /**
   * Get adapter by source ID
   */
  get(sourceId: SearchSource): SearchSourceAdapter | undefined {
    return this.adapters.get(sourceId);
  }

  /**
   * Get all registered adapters
   */
  getAll(): SearchSourceAdapter[] {
    return Array.from(this.adapters.values());
  }

  /**
   * Get only available adapters (API keys present, etc.)
   */
  getAvailable(): SearchSourceAdapter[] {
    return this.getAll().filter(a => a.isAvailable());
  }

  /**
   * Get adapters by tier
   */
  getByTier(tier: SourceTier): SearchSourceAdapter[] {
    return this.getAll().filter(a => a.meta.tier === tier);
  }

  /**
   * Get adapters by domain
   */
  getByDomain(domain: SourceDomain): SearchSourceAdapter[] {
    return this.getAll().filter(a => a.meta.domains.includes(domain));
  }

  /**
   * Get available adapters filtered by source IDs, maintaining order
   */
  getBySourceIds(sourceIds: SearchSource[]): SearchSourceAdapter[] {
    const result: SearchSourceAdapter[] = [];
    for (const id of sourceIds) {
      const adapter = this.adapters.get(id);
      if (adapter && adapter.isAvailable()) {
        result.push(adapter);
      }
    }
    return result;
  }

  /**
   * Check if a source is registered and available
   */
  isAvailable(sourceId: SearchSource): boolean {
    const adapter = this.adapters.get(sourceId);
    return adapter ? adapter.isAvailable() : false;
  }

  /**
   * Get all registered source IDs
   */
  getSourceIds(): SearchSource[] {
    return Array.from(this.adapters.keys());
  }
}

/**
 * Semantic Scholar Adapter
 */

import { AbstractSearchAdapter, type AdapterMeta } from './base';
import type { SearchResult, SemanticScholarPaper } from '../types';
import { getErrorMessage } from '../../../shared/errors';

const S2_API_URL = 'https://api.semanticscholar.org/graph/v1';

export class SemanticScholarAdapter extends AbstractSearchAdapter {
  readonly meta: AdapterMeta = {
    name: 'Semantic Scholar',
    sourceId: 'semantic_scholar',
    tier: 'free',
    domains: ['general', 'cs', 'biomedical', 'multidisciplinary'],
    rateLimit: { requests: 10, windowMs: 1000 },
    description: 'AI-powered academic search engine with 200M+ papers'
  };

  isAvailable(): boolean {
    return true; // No API key required (has optional key for higher limits)
  }

  async search(query: string, limit: number): Promise<SearchResult[]> {
    try {
      const fields = 'paperId,title,abstract,authors,year,citationCount,venue,url,openAccessPdf';
      const url = `${S2_API_URL}/paper/search?query=${encodeURIComponent(query)}&limit=${limit}&fields=${fields}`;

      const response = await this.rateLimitedFetch(url, undefined, { maxRetries: 3 });
      const data = await response.json() as { data?: SemanticScholarPaper[] };

      if (!data.data) return [];

      return data.data.map((paper) => ({
        id: paper.paperId,
        title: paper.title,
        authors: paper.authors.map(a => a.name),
        abstract: paper.abstract || '',
        publishDate: paper.year?.toString() || '',
        source: 'semantic_scholar',
        url: paper.url,
        pdfUrl: paper.openAccessPdf?.url,
        citations: paper.citationCount,
        venue: paper.venue,
        openAccess: !!paper.openAccessPdf
      }));
    } catch (error) {
      console.error('Semantic Scholar search error:', getErrorMessage(error));
      return [];
    }
  }
}

/**
 * Unpaywall Adapter - DOI-to-OA-PDF resolver
 * Not a search engine - resolves DOIs to open access PDF URLs
 */

import { AbstractSearchAdapter, type AdapterMeta } from './base';
import type { SearchResult } from '../types';
import { getErrorMessage } from '../../../shared/errors';

const UNPAYWALL_API_URL = 'https://api.unpaywall.org/v2';

export class UnpaywallAdapter extends AbstractSearchAdapter {
  readonly meta: AdapterMeta = {
    name: 'Unpaywall',
    sourceId: 'unpaywall',
    tier: 'free',
    domains: ['general', 'multidisciplinary'],
    rateLimit: { requests: 10, windowMs: 1000 },
    description: 'DOI-to-open-access PDF resolver (enrichment, not search)'
  };

  private email?: string;

  constructor(email?: string) {
    super();
    this.email = email || process.env.UNPAYWALL_EMAIL;
  }

  isAvailable(): boolean {
    return !!this.email;
  }

  /**
   * Unpaywall is not a search engine - returns empty for search queries.
   * Use getPdfUrl() to resolve DOIs to PDF URLs.
   */
  async search(_query: string, _limit: number): Promise<SearchResult[]> {
    return []; // Not a search engine
  }

  /**
   * Resolve a DOI to an open access PDF URL
   */
  async getPdfUrl(result: SearchResult): Promise<string | undefined> {
    if (!this.email || !result.doi) return undefined;

    try {
      const url = `${UNPAYWALL_API_URL}/${encodeURIComponent(result.doi)}?email=${encodeURIComponent(this.email)}`;
      const response = await this.rateLimitedFetch(url);
      const data = await response.json() as {
        best_oa_location?: {
          url_for_pdf?: string;
          url?: string;
        };
        is_oa?: boolean;
      };

      return data.best_oa_location?.url_for_pdf || data.best_oa_location?.url;
    } catch (error) {
      console.error('Unpaywall lookup error:', getErrorMessage(error));
      return undefined;
    }
  }

  /**
   * Batch resolve DOIs
   */
  async batchResolvePdfUrls(results: SearchResult[]): Promise<Map<string, string>> {
    const urlMap = new Map<string, string>();
    const resultsWithDois = results.filter(r => r.doi && !r.pdfUrl);

    for (const result of resultsWithDois) {
      const pdfUrl = await this.getPdfUrl(result);
      if (pdfUrl && result.doi) {
        urlMap.set(result.doi, pdfUrl);
      }
    }

    return urlMap;
  }
}

