/**
 * PDF Downloader - Multi-strategy PDF download module
 * PDF 下载器 - 多策略 PDF 下载模块
 */

import { existsSync, mkdirSync, writeFileSync, readFileSync } from 'fs';
import { join, resolve } from 'path';
import type { SearchResult, PdfDownloadOptions, PdfDownloadResult, PdfMetadataIndex } from './types';
import type { UnpaywallAdapter } from './adapters/unpaywall-adapter';
import type { SearchSourceRegistry } from './adapters/registry';
import { getErrorMessage } from '../../shared/errors';

const DEFAULT_OPTIONS: Required<PdfDownloadOptions> = {
  outputDir: './downloads/pdfs',
  maxFileSize: 50 * 1024 * 1024, // 50MB
  skipExisting: true,
  concurrency: 3,
  namingStrategy: 'title'
};

/** PDF magic bytes check */
const PDF_MAGIC = '%PDF';

export class PdfDownloader {
  private options: Required<PdfDownloadOptions>;
  private registry?: SearchSourceRegistry;
  private unpaywallAdapter?: UnpaywallAdapter;

  constructor(options?: PdfDownloadOptions, registry?: SearchSourceRegistry) {
    this.options = { ...DEFAULT_OPTIONS, ...options };
    this.registry = registry;

    // Try to get Unpaywall adapter from registry
    if (registry) {
      const unpaywall = registry.get('unpaywall');
      if (unpaywall && 'getPdfUrl' in unpaywall) {
        this.unpaywallAdapter = unpaywall as UnpaywallAdapter;
      }
    }
  }

  /**
   * Download PDFs for search results
   */
  async downloadResults(results: SearchResult[]): Promise<PdfDownloadResult[]> {
    // Ensure output directory exists
    const outputDir = resolve(this.options.outputDir);
    if (!existsSync(outputDir)) {
      mkdirSync(outputDir, { recursive: true });
    }

    const downloadResults: PdfDownloadResult[] = [];

    // Process in batches based on concurrency limit
    for (let i = 0; i < results.length; i += this.options.concurrency) {
      const batch = results.slice(i, i + this.options.concurrency);
      const batchPromises = batch.map(result =>
        this.downloadSingle(result, outputDir)
          .then(dlResult => {
            if (dlResult) downloadResults.push(dlResult);
          })
          .catch(err => {
            console.error(`Failed to download "${result.title}":`, getErrorMessage(err));
          })
      );
      await Promise.allSettled(batchPromises);
    }

    // Update metadata index
    this.updateMetadataIndex(outputDir, downloadResults, results);

    return downloadResults;
  }

  /**
   * Download a single PDF
   */
  private async downloadSingle(
    result: SearchResult,
    outputDir: string
  ): Promise<PdfDownloadResult | null> {
    const filename = this.generateFilename(result);
    const filePath = join(outputDir, filename);

    // Skip existing
    if (this.options.skipExisting && existsSync(filePath)) {
      console.log(`  Skipping (exists): ${filename}`);
      return null;
    }

    // Resolve PDF URL
    const pdfUrl = await this.resolvePdfUrl(result);
    if (!pdfUrl) {
      console.log(`  No PDF URL found for: ${result.title}`);
      return null;
    }

    try {
      console.log(`  Downloading: ${filename}`);
      const response = await fetch(pdfUrl, {
        headers: {
          'User-Agent': 'ScholarGraph/1.0 (academic research tool)',
          'Accept': 'application/pdf'
        },
        redirect: 'follow'
      });

      if (!response.ok) {
        console.error(`  HTTP ${response.status} for ${pdfUrl}`);
        return null;
      }

      // Check content length
      const contentLength = response.headers.get('content-length');
      if (contentLength && parseInt(contentLength) > this.options.maxFileSize) {
        console.error(`  File too large (${contentLength} bytes): ${filename}`);
        return null;
      }

      const buffer = Buffer.from(await response.arrayBuffer());

      // Size check on actual content
      if (buffer.length > this.options.maxFileSize) {
        console.error(`  File too large (${buffer.length} bytes): ${filename}`);
        return null;
      }

      // PDF magic bytes verification
      const header = buffer.slice(0, 4).toString('ascii');
      if (!header.startsWith(PDF_MAGIC)) {
        console.error(`  Not a valid PDF (header: ${header}): ${filename}`);
        return null;
      }

      writeFileSync(filePath, buffer);
      console.log(`  Saved: ${filename} (${(buffer.length / 1024).toFixed(1)} KB)`);

      return {
        filePath,
        title: result.title,
        source: result.source,
        size: buffer.length,
        doi: result.doi
      };
    } catch (error) {
      console.error(`  Download error: ${getErrorMessage(error)}`);
      return null;
    }
  }

  /**
   * Multi-strategy PDF URL resolution
   */
  private async resolvePdfUrl(result: SearchResult): Promise<string | undefined> {
    // Strategy 1: Direct pdfUrl from search result
    if (result.pdfUrl) return result.pdfUrl;

    // Strategy 2: Unpaywall lookup by DOI
    if (result.doi && this.unpaywallAdapter?.isAvailable()) {
      const url = await this.unpaywallAdapter.getPdfUrl(result);
      if (url) return url;
    }

    // Strategy 3: OpenAlex OA location (already in pdfUrl if from OpenAlex)

    // Strategy 4: CORE full text
    if (result.doi && this.registry) {
      const coreAdapter = this.registry.get('core');
      if (coreAdapter && 'getPdfUrl' in coreAdapter && coreAdapter.isAvailable()) {
        const url = await (coreAdapter as any).getPdfUrl(result);
        if (url) return url;
      }
    }

    return undefined;
  }

  /**
   * Generate filename from result
   */
  private generateFilename(result: SearchResult): string {
    let baseName: string;

    switch (this.options.namingStrategy) {
      case 'doi':
        baseName = result.doi ? result.doi.replace(/[/\\:]/g, '_') : this.sanitizeTitle(result.title);
        break;
      case 'id':
        baseName = result.id.replace(/[/\\:]/g, '_');
        break;
      case 'title':
      default:
        baseName = this.sanitizeTitle(result.title);
        break;
    }

    return `${baseName}.pdf`;
  }

  /**
   * Sanitize title for use as filename
   */
  private sanitizeTitle(title: string): string {
    return title
      .replace(/[<>:"/\\|?*]/g, '')
      .replace(/\s+/g, '_')
      .substring(0, 100)
      .replace(/_+$/, '');
  }

  /**
   * Update metadata.json index
   */
  private updateMetadataIndex(
    outputDir: string,
    downloadResults: PdfDownloadResult[],
    searchResults: SearchResult[]
  ): void {
    const indexPath = join(outputDir, 'metadata.json');

    let index: PdfMetadataIndex = { files: [] };

    // Load existing index
    try {
      if (existsSync(indexPath)) {
        index = JSON.parse(readFileSync(indexPath, 'utf-8'));
      }
    } catch { /* ignore */ }

    // Add new entries
    for (const dl of downloadResults) {
      const searchResult = searchResults.find(r => r.title === dl.title);
      if (!searchResult) continue;

      // Check if already indexed
      if (index.files.some(f => f.filePath === dl.filePath)) continue;

      index.files.push({
        filePath: dl.filePath,
        title: dl.title,
        authors: searchResult.authors,
        source: dl.source,
        doi: dl.doi,
        url: searchResult.url,
        downloadedAt: new Date().toISOString()
      });
    }

    writeFileSync(indexPath, JSON.stringify(index, null, 2));
  }
}

/**
 * Query Expander - 查询扩展模块
 *
 * 将用户模糊的研究兴趣转化为具体的搜索关键词
 */

import { createAIProvider, type AIProvider } from '../../shared/ai-provider';
import { ApiInitializationError, getErrorMessage } from '../../shared/errors';

export interface QueryExpansionResult {
  // 确认的用户需求信息
  confirmation: {
    coreTheme?: string;        // 核心主题
    subField?: string;         // 子领域/方向
    applicationScenario?: string; // 应用场景
    timeRange?: string;        // 时间范围
    preferredSources?: string; // 偏好来源
  };

  // 生成的关键词列表
  keywords: Array<{
    term: string;              // 关键词
    description: string;       // 简短说明
    type: 'core' | 'synonym' | 'abbreviation' | 'related' | 'application'; // 关键词类型
  }>;

  // 追问问题（如果需要更多信息）
  followUpQuestions?: string[];

  // 是否需要更多信息
  needsMoreInfo: boolean;
}

export default class QueryExpander {
  private ai: AIProvider | null = null;

  async initialize(): Promise<void> {
    if (!this.ai) {
      try {
        this.ai = await createAIProvider();
      } catch (error) {
        throw new ApiInitializationError(
          `Failed to initialize AI provider: ${getErrorMessage(error)}`,
          error instanceof Error ? error : undefined
        );
      }
    }
  }

  /**
   * 扩展用户查询，生成多个搜索关键词
   */
  async expandQuery(userInput: string, context?: string): Promise<QueryExpansionResult> {
    await this.initialize();

    const systemPrompt = `你是一个专业的学术文献搜索助手 "Literature Search Prompt Engineer"。
你的任务是根据用户模糊的研究兴趣，通过分析来厘清领域，并生成多个可执行的搜索关键词。

## 工作流程

### 阶段 1：理解需求
用户给你的输入可能是模糊的，你需要分析以下信息：
1. **核心主题**：具体想研究什么？
2. **子领域/方向**：更具体的角度？
3. **应用场景**：研究目的是什么？
4. **时间范围**：需要多新的论文？
5. **偏好来源**：对某些期刊/会议有偏好吗？

### 阶段 2：生成关键词
生成关键词的策略：
- **核心词**：用户提到的核心概念
- **同义词**：常见的替换词
- **缩写**：全称和缩写都要
- **相关术语**：上下游技术、工具、框架
- **应用领域**：具体应用场景

### 输出格式
返回 JSON 格式：
{
  "confirmation": {
    "coreTheme": "核心主题",
    "subField": "子领域",
    "applicationScenario": "应用场景",
    "timeRange": "时间范围",
    "preferredSources": "偏好来源"
  },
  "keywords": [
    {
      "term": "关键词",
      "description": "说明",
      "type": "core|synonym|abbreviation|related|application"
    }
  ],
  "followUpQuestions": ["问题1", "问题2"],
  "needsMoreInfo": true/false
}`;

    const userPrompt = context
      ? `用户输入：${userInput}\n\n上下文信息：${context}\n\n请分析用户需求并生成搜索关键词。`
      : `用户输入：${userInput}\n\n请分析用户需求并生成搜索关键词。`;

    try {
      const response = await this.ai!.chat([
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ], { temperature: 0.7 });

      // 尝试解析 JSON 响应
      const jsonMatch = response.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        const result = JSON.parse(jsonMatch[0]);
        return result as QueryExpansionResult;
      }

      // 如果无法解析 JSON，返回基础结果
      return {
        confirmation: {
          coreTheme: userInput
        },
        keywords: [
          {
            term: userInput,
            description: '用户原始输入',
            type: 'core'
          }
        ],
        needsMoreInfo: true,
        followUpQuestions: [
          '你更偏向于哪个具体方向？',
          '是为了写论文、找创新点，还是为了工程应用？'
        ]
      };
    } catch (error) {
      throw new Error(`Query expansion failed: ${getErrorMessage(error)}`);
    }
  }

  /**
   * 交互式查询扩展（多轮对话）
   */
  async interactiveExpand(
    userInput: string,
    conversationHistory: Array<{ role: 'user' | 'assistant'; content: string }> = []
  ): Promise<QueryExpansionResult> {
    await this.initialize();

    const systemPrompt = `你是一个专业的学术文献搜索助手。通过多轮对话来帮助用户明确研究方向并生成搜索关键词。

每次对话都要：
1. 理解用户的回答
2. 更新对用户需求的理解
3. 如果信息足够，生成关键词列表
4. 如果信息不足，提出1-2个关键问题

返回 JSON 格式的结果。`;

    const messages = [
      { role: 'system' as const, content: systemPrompt },
      ...conversationHistory,
      { role: 'user' as const, content: userInput }
    ];

    try {
      const response = await this.ai!.chat(messages, { temperature: 0.7 });

      const jsonMatch = response.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        const result = JSON.parse(jsonMatch[0]);
        return result as QueryExpansionResult;
      }

      return {
        confirmation: {},
        keywords: [],
        needsMoreInfo: true,
        followUpQuestions: ['请提供更多信息以帮助我理解你的研究方向。']
      };
    } catch (error) {
      throw new Error(`Interactive expansion failed: ${getErrorMessage(error)}`);
    }
  }

  /**
   * 格式化输出结果（用于 CLI 显示）
   */
  formatResult(result: QueryExpansionResult): string {
    let output = '\n📋 确认信息：\n';

    const { confirmation } = result;
    if (confirmation.coreTheme) output += `- 核心主题：${confirmation.coreTheme}\n`;
    if (confirmation.subField) output += `- 子领域：${confirmation.subField}\n`;
    if (confirmation.applicationScenario) output += `- 应用场景：${confirmation.applicationScenario}\n`;
    if (confirmation.timeRange) output += `- 时间范围：${confirmation.timeRange}\n`;
    if (confirmation.preferredSources) output += `- 偏好来源：${confirmation.preferredSources}\n`;

    if (result.keywords.length > 0) {
      output += '\n🔍 建议关键词：\n';
      result.keywords.forEach((kw, index) => {
        const typeEmoji = {
          core: '🎯',
          synonym: '🔄',
          abbreviation: '📝',
          related: '🔗',
          application: '💡'
        }[kw.type] || '•';
        output += `${index + 1}. ${typeEmoji} ${kw.term} - ${kw.description}\n`;
      });
    }

    if (result.followUpQuestions && result.followUpQuestions.length > 0) {
      output += '\n❓ 追问：\n';
      result.followUpQuestions.forEach((q, index) => {
        output += `${index + 1}. ${q}\n`;
      });
    }

    return output;
  }
}

/**
 * Complementary Search Strategy
 * 互补搜索策略 - 根据查询自动选择最优数据源组合
 */

import type { SearchSource } from '../../shared/types';
import type { SearchSourceRegistry } from './adapters/registry';

/** Domain detection keywords */
const DOMAIN_KEYWORDS: Record<string, string[]> = {
  biomedical: [
    'gene', 'protein', 'genome', 'clinical', 'drug', 'disease', 'medical',
    'surgery', 'patient', 'therapy', 'cancer', 'cell', 'dna', 'rna',
    'molecular', 'biology', 'pathology', 'neuroscience', 'brain',
    'pharmaceutical', 'crispr', 'biomarker', 'epidemiology', 'virus',
    'vaccine', 'immune', 'metabol', 'cardio', 'oncology',
    '基因', '蛋白质', '临床', '药物', '疾病', '细胞', '分子', '生物'
  ],
  cs: [
    'algorithm', 'neural network', 'deep learning', 'machine learning',
    'transformer', 'nlp', 'computer vision', 'natural language', 'software',
    'compiler', 'database', 'distributed', 'operating system', 'gpu',
    'reinforcement learning', 'generative', 'llm', 'language model',
    'attention mechanism', 'bert', 'gpt', 'convolutional', 'recurrent',
    'classification', 'segmentation', 'object detection',
    '算法', '神经网络', '深度学习', '机器学习', '自然语言'
  ],
  engineering: [
    'circuit', 'signal processing', 'antenna', 'semiconductor', 'vlsi',
    'embedded', 'control system', 'robotics', 'sensor', 'actuator',
    'power electronics', 'communication system', 'wireless', '5g', '6g',
    'iot', 'fpga', 'microprocessor', 'rf',
    '电路', '信号处理', '半导体', '传感器', '机器人'
  ],
  physics: [
    'quantum', 'particle', 'cosmology', 'astrophysics', 'condensed matter',
    'gravitational', 'photon', 'dark matter', 'dark energy', 'superconductor',
    'plasma', 'relativity', 'boson', 'fermion', 'higgs', 'string theory',
    'thermodynamics', 'optics', 'laser', 'nuclear',
    '量子', '粒子', '宇宙', '凝聚态', '光学'
  ]
};

/** Default priority order */
const DEFAULT_PRIORITY: SearchSource[] = [
  'semantic_scholar', 'openalex', 'arxiv', 'pubmed',
  'crossref', 'dblp', 'core', 'ieee', 'web'
];

/** Domain-specific priority orders */
const DOMAIN_PRIORITIES: Record<string, SearchSource[]> = {
  biomedical: ['pubmed', 'semantic_scholar', 'openalex', 'crossref'],
  cs: ['semantic_scholar', 'arxiv', 'dblp', 'openalex'],
  engineering: ['ieee', 'semantic_scholar', 'openalex', 'crossref'],
  physics: ['arxiv', 'semantic_scholar', 'openalex'],
  general: ['semantic_scholar', 'openalex', 'crossref', 'arxiv']
};

export interface StrategyConfig {
  defaultPriority?: SearchSource[];
  domainPriorities?: Record<string, SearchSource[]>;
  maxConcurrentSources?: number;
  useComplementaryStrategy?: boolean;
}

export class ComplementarySearchStrategy {
  private config: Required<StrategyConfig>;

  constructor(config?: StrategyConfig) {
    this.config = {
      defaultPriority: config?.defaultPriority || DEFAULT_PRIORITY,
      domainPriorities: config?.domainPriorities || DOMAIN_PRIORITIES,
      maxConcurrentSources: config?.maxConcurrentSources || 4,
      useComplementaryStrategy: config?.useComplementaryStrategy ?? true
    };
  }

  /**
   * Detect academic domain from query keywords
   */
  detectDomain(query: string): string {
    const lowerQuery = query.toLowerCase();

    const scores: Record<string, number> = {};
    for (const [domain, keywords] of Object.entries(DOMAIN_KEYWORDS)) {
      scores[domain] = keywords.filter(kw => lowerQuery.includes(kw)).length;
    }

    // Find domain with highest score
    let bestDomain = 'general';
    let bestScore = 0;
    for (const [domain, score] of Object.entries(scores)) {
      if (score > bestScore) {
        bestScore = score;
        bestDomain = domain;
      }
    }

    return bestScore > 0 ? bestDomain : 'general';
  }

  /**
   * Select optimal sources for a query
   */
  selectSources(
    query: string,
    registry: SearchSourceRegistry,
    domainHint?: string
  ): SearchSource[] {
    if (!this.config.useComplementaryStrategy) {
      return this.config.defaultPriority
        .filter(s => registry.isAvailable(s))
        .slice(0, this.config.maxConcurrentSources);
    }

    const domain = domainHint || this.detectDomain(query);
    const priority = this.config.domainPriorities[domain] || this.config.defaultPriority;

    const selected: SearchSource[] = [];
    const usedIds = new Set<SearchSource>();

    // 1. Add sources from domain priority list
    for (const sourceId of priority) {
      if (selected.length >= this.config.maxConcurrentSources) break;
      if (registry.isAvailable(sourceId) && !usedIds.has(sourceId)) {
        selected.push(sourceId);
        usedIds.add(sourceId);
      }
    }

    // 2. Fill remaining slots from default priority
    if (selected.length < this.config.maxConcurrentSources) {
      for (const sourceId of this.config.defaultPriority) {
        if (selected.length >= this.config.maxConcurrentSources) break;
        if (registry.isAvailable(sourceId) && !usedIds.has(sourceId)) {
          selected.push(sourceId);
          usedIds.add(sourceId);
        }
      }
    }

    return selected;
  }

  /**
   * Get the detected or hinted domain for display
   */
  getDomainInfo(query: string, domainHint?: string): { domain: string; isHinted: boolean } {
    if (domainHint) {
      return { domain: domainHint, isHinted: true };
    }
    return { domain: this.detectDomain(query), isHinted: false };
  }
}

/**
 * Literature Search - Core Module
 * 文献检索核心模块
 *
 * 提供多源文献检索能力，使用适配器注册表模式：
 * - arXiv, Semantic Scholar, Web (原有)
 * - OpenAlex, PubMed, CrossRef, DBLP (免费源)
 * - IEEE, CORE, Unpaywall, Google Scholar (需 API Key)
 */

import { createAIProvider, type AIProvider } from '../../shared/ai-provider';
import { normalizeTitle, withTimeout } from '../../shared/utils';
import { ApiInitializationError, getErrorMessage } from '../../shared/errors';
import type { SearchSource } from '../../shared/types';
import type { SearchOptions, SearchResult, SearchResponse } from './types';

import { SearchSourceRegistry } from './adapters/registry';
import { ArxivAdapter } from './adapters/arxiv-adapter';
import { SemanticScholarAdapter } from './adapters/semantic-scholar-adapter';
import { WebAdapter } from './adapters/web-adapter';
import { OpenAlexAdapter } from './adapters/openalex-adapter';
import { PubMedAdapter } from './adapters/pubmed-adapter';
import { CrossRefAdapter } from './adapters/crossref-adapter';
import { DblpAdapter } from './adapters/dblp-adapter';
import { IeeeAdapter } from './adapters/ieee-adapter';
import { CoreAdapter } from './adapters/core-adapter';
import { UnpaywallAdapter } from './adapters/unpaywall-adapter';
import { GoogleScholarAdapter } from './adapters/google-scholar-adapter';
import { ComplementarySearchStrategy } from './search-strategy';

// 默认超时时间
const DEFAULT_TIMEOUT_MS = 30000;

export default class LiteratureSearch {
  private ai: AIProvider | null = null;
  private registry: SearchSourceRegistry;
  private strategy: ComplementarySearchStrategy;
  private webAdapter: WebAdapter;

  constructor() {
    this.registry = new SearchSourceRegistry();
    this.strategy = new ComplementarySearchStrategy();
    this.webAdapter = new WebAdapter();

    // Register all adapters
    this.registry.register(new ArxivAdapter());
    this.registry.register(new SemanticScholarAdapter());
    this.registry.register(this.webAdapter);
    this.registry.register(new OpenAlexAdapter());
    this.registry.register(new PubMedAdapter());
    this.registry.register(new CrossRefAdapter());
    this.registry.register(new DblpAdapter());
    this.registry.register(new IeeeAdapter());
    this.registry.register(new CoreAdapter());
    this.registry.register(new UnpaywallAdapter());
    this.registry.register(new GoogleScholarAdapter());
  }

  /**
   * 初始化搜索器
   */
  async initialize(): Promise<void> {
    if (!this.ai) {
      try {
        this.ai = await createAIProvider();
        this.webAdapter.setAIProvider(this.ai);
      } catch (error) {
        throw new ApiInitializationError(
          `Failed to initialize AI provider: ${getErrorMessage(error)}`,
          error instanceof Error ? error : undefined
        );
      }
    }
  }

  /**
   * Get the adapter registry
   */
  getRegistry(): SearchSourceRegistry {
    return this.registry;
  }

  /**
   * Get the search strategy
   */
  getStrategy(): ComplementarySearchStrategy {
    return this.strategy;
  }

  /**
   * 综合搜索入口
   */
  async search(query: string, options: SearchOptions = {}): Promise<SearchResponse> {
    await this.initialize();

    const {
      limit = 10,
      sortBy = 'relevance',
      domainHint,
      filters
    } = options;

    let sources: SearchSource[];

    if (options.sources && options.sources.length > 0) {
      // Explicit sources specified
      sources = options.sources;
    } else {
      // Auto-select using complementary strategy
      sources = this.strategy.selectSources(query, this.registry, domainHint);
    }

    const allResults: SearchResult[] = [];
    const usedSources: string[] = [];

    // 并行搜索多个数据源（带超时）
    const searchPromises: Promise<SearchResult[]>[] = [];

    for (const sourceId of sources) {
      const adapter = this.registry.get(sourceId);
      if (!adapter || !adapter.isAvailable()) continue;

      // Skip unpaywall for search (it's an enrichment source)
      if (sourceId === 'unpaywall') continue;

      searchPromises.push(
        withTimeout(
          adapter.search(query, limit),
          DEFAULT_TIMEOUT_MS,
          `${adapter.meta.name} search`
        ).catch(err => {
          console.error(`${adapter.meta.name} search failed:`, getErrorMessage(err));
          return [];
        })
      );
      usedSources.push(sourceId);
    }

    const results = await Promise.allSettled(searchPromises);

    // 合并结果
    results.forEach((result) => {
      if (result.status === 'fulfilled') {
        allResults.push(...result.value);
      }
    });

    // 应用过滤
    let filtered = this.applyFilters(allResults, filters);

    // 排序
    filtered = this.sortResults(filtered, sortBy);

    // 限制结果数量
    filtered = filtered.slice(0, limit * usedSources.length);

    // 去重（基于标题相似度）
    filtered = this.deduplicateResults(filtered);

    return {
      query,
      totalResults: filtered.length,
      results: filtered.slice(0, limit),
      sources: usedSources,
      timestamp: new Date().toISOString()
    };
  }

  /**
   * 按作者搜索
   */
  async searchByAuthor(authorName: string, options: SearchOptions = {}): Promise<SearchResponse> {
    const query = `author:"${authorName}"`;
    return this.search(query, { ...options, sources: ['arxiv', 'semantic_scholar'] });
  }

  /**
   * 应用过滤条件
   */
  private applyFilters(results: SearchResult[], filters?: SearchOptions['filters']): SearchResult[] {
    if (!filters) return results;

    let filtered = [...results];

    // 年份过滤
    if (filters.yearRange) {
      const [start, end] = filters.yearRange;
      filtered = filtered.filter(r => {
        const year = parseInt(r.publishDate.split('-')[0]);
        return !isNaN(year) && year >= start && year <= end;
      });
    }

    // 最小引用数过滤
    if (filters.minCitations) {
      filtered = filtered.filter(r =>
        !r.citations || r.citations >= filters.minCitations!
      );
    }

    // 分类过滤
    if (filters.categories?.length) {
      filtered = filtered.filter(r =>
        r.keywords?.some(k => filters.categories!.includes(k))
      );
    }

    return filtered;
  }

  /**
   * 排序结果
   */
  private sortResults(results: SearchResult[], sortBy: string): SearchResult[] {
    const sorted = [...results];

    switch (sortBy) {
      case 'citations':
        return sorted.sort((a, b) => (b.citations || 0) - (a.citations || 0));
      case 'date':
        return sorted.sort((a, b) =>
          new Date(b.publishDate).getTime() - new Date(a.publishDate).getTime()
        );
      default:
        return sorted; // 按相关性（API默认顺序）
    }
  }

  /**
   * 去重（基于标题相似度）
   */
  private deduplicateResults(results: SearchResult[]): SearchResult[] {
    const seen = new Set<string>();
    const deduped: SearchResult[] = [];

    for (const result of results) {
      const normalizedTitle = normalizeTitle(result.title);

      if (!seen.has(normalizedTitle)) {
        seen.add(normalizedTitle);
        deduped.push(result);
      }
    }

    return deduped;
  }
}

// CLI 支持
if (import.meta.main) {
  const args = process.argv.slice(2);
  const query = args[0];

  if (!query) {
    console.error('Usage: bun run search.ts <query> [--limit N] [--source <source>]');
    process.exit(1);
  }

  const limitIndex = args.indexOf('--limit');
  const limit = limitIndex > -1 ? parseInt(args[limitIndex + 1]) || 10 : 10;

  const sourceIndex = args.indexOf('--source');
  const source = sourceIndex > -1 ? args[sourceIndex + 1] as SearchSource : undefined;

  const searcher = new LiteratureSearch();

  searcher.search(query, {
    limit,
    sources: source ? [source] : undefined
  }).then(response => {
    console.log(JSON.stringify(response, null, 2));
  }).catch(err => {
    console.error('Search failed:', getErrorMessage(err));
    process.exit(1);
  });
}

